text:
printf 'package p

func f() { var x float64 = 1 ; _ = x }
'          > "$TMP/corpus/g1-clean-float64.go"

printf 'package p

func f() { var \xe2 x float64 = 1 ; _ = x }
'     > "$TMP/corpus/g2-poison-before-same-line.go"

printf 'package p

func f() { var x int64 = 1 ; _ = x }
'            > "$TMP/corpus/g3-clean-int.go"

printf '{
  "note": "x", \xe2 "rate_pct": 3.6
}
'     > "$P/p7.json"  # same as p2, for the e2e plant

printf 'package x

func A() { var v float64; _ = v }
'                        > "$P/g1.go"

printf 'package x

func A() { s := "\xe2"; var v float64; _ = v; _ = s }
'    > "$P/g2.go"

printf 'package x

func A() { var v int64; _ = v }
'                          > "$P/g3.go"

printf 'package x

func A() { var v int64; _ = v }
' > "$T/zero/goodgo/internal/apps/loanschedule/ok.go"

printf 'package x

func A() { var v float64; _ = v }
' > "$T/zero/badgo/internal/apps/loanschedule/bad.go"
